#!/usr/bin/env tsx
/**
 * Setup interactif pour light-ts
 * Usage: pnpm setup
 *
 * Guide l'utilisateur pour configurer:
 * 1. Vérifier les CLIs (gh, vercel, neon, stripe)
 * 2. Configurer Vercel
 * 3. Configurer NeonDB
 * 4. Configurer Stripe (optionnel)
 * 5. Générer .env.local
 * 6. Migrer la DB
 */

