  console.log(
    "╔══════════════════════════════════════════════════════════════╗",
  );
  console.log(
    "║                     light-ts Setup                           ║",
  );
  console.log(
    "║              Configuration interactive du projet             ║",
  );
  console.log(
    "╚══════════════════════════════════════════════════════════════╝",
  );
