  console.log("\n");
  console.log(
    "╔══════════════════════════════════════════════════════════════╗",
  );
  console.log(
    "║                     light-ts Setup                           ║",
  );
  console.log(
    "║              Configuration interactive du projet             ║",
  );
  console.log(
    "╚══════════════════════════════════════════════════════════════╝",
  );
  console.log("\n");

  try {
    await checkCLIs();

    const vercelEnv = await setupVercel();
